/// that emits [`LogEntry`]s in log order — both the backlog already decided
/// at subscription time and entries decided later.
///
/// Each call creates an independent subscription with its own cursor;
/// multiple subscribers can coexist, up to [`RuntimeConfig::max_decided_subscribers`]
/// — beyond that, the returned receiver's channel is closed immediately
/// without delivering any entries. Dropping the receiver ends the
/// subscription; slow subscribers apply backpressure by causing the actor
/// to defer pushes rather than blocking the actor loop.
pub async fn subscribe_decided(&self, from: usize) -> async_channel::Receiver<LogEntry<T>> {
    let (tx, rx) = async_channel::bounded(self.decided_channel_capacity);
    // If the actor is gone, `rx` stays open but never receives — the
    // caller's stream drops naturally when the sender is dropped here.
    let _ = self
        .cmd_tx
        .send(Command::SubscribeDecided { from, tx })
        .await;
    rx
}

pub(crate) fn sync_log(
    &mut self,
    accepted_round: Ballot,
    decided_idx: usize,
    log_sync: Option<LogSync<T>>,
) -> StorageResult<usize> {
    self.state_cache.accepted_round = accepted_round;
    self.state_cache.decided_idx = decided_idx;
    let mut sync_txn: Vec<StorageOp<T>> = vec![
        StorageOp::SetAcceptedRound(accepted_round),
        StorageOp::SetDecidedIndex(decided_idx),
    ];
    if let Some(sync) = log_sync {
        match sync.decided_snapshot {
            Some(SnapshotType::Complete(c)) => {
                self.state_cache.compacted_idx = sync.sync_idx;
                sync_txn.push(StorageOp::Trim(sync.sync_idx));
                sync_txn.push(StorageOp::SetCompactedIdx(sync.sync_idx));
                sync_txn.push(StorageOp::SetSnapshot(Some(c)));
            }
            Some(SnapshotType::Delta(d)) => {
                let mut snapshot = self.create_decided_snapshot()?;
                snapshot.merge(d);
                self.state_cache.compacted_idx = sync.sync_idx;
                sync_txn.push(StorageOp::Trim(sync.sync_idx));
                sync_txn.push(StorageOp::SetCompactedIdx(sync.sync_idx));
                sync_txn.push(StorageOp::SetSnapshot(Some(snapshot)));
            }
            None => (),
        }
        self.state_cache.accepted_idx = sync.sync_idx + sync.suffix.len();
        sync_txn.push(StorageOp::AppendOnPrefix(sync.sync_idx, sync.suffix));
        match sync.stopsign {
            Some(ss) => {
                self.state_cache.stopsign = Some(ss.clone());
                self.state_cache.accepted_idx += 1;
                sync_txn.push(StorageOp::SetStopsign(Some(ss)));
            }
            None if self.state_cache.stopsign.is_some() => {
                self.state_cache.stopsign = None;
                sync_txn.push(StorageOp::SetStopsign(None));
            }
            None => (),
        }
    }
    self.storage.write_atomically(sync_txn)?;
    Ok(self.state_cache.accepted_idx)
}

pub(crate) fn handle_acceptsync(&mut self, accsync: AcceptSync<T>, from: NodeId) {
    if self.check_valid_ballot(accsync.n) && self.state == (Role::Follower, Phase::Prepare) {
        self.cached_promise_message = None;
        let new_accepted_idx = self
            .internal_storage
            .sync_log(accsync.n, accsync.decided_idx, Some(accsync.log_sync))
            .expect(WRITE_ERROR_MSG);
        if self.internal_storage.get_stopsign().is_none() {
            self.forward_buffered_proposals();
        }
        let accepted = Accepted {
            n: accsync.n,
            accepted_idx: new_accepted_idx,
        };
        self.state = (Role::Follower, Phase::Accept);
        self.current_seq_num = accsync.seq_num;
        let cached_idx = self.outgoing.len();
        self.latest_accepted_meta = Some((accsync.n, cached_idx));
        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
            from: self.pid,
            to: from,
            msg: PaxosMsg::Accepted(accepted),
        }));
        #[cfg(feature = "unicache")]
        self.internal_storage.set_unicache(accsync.unicache);
    }
}

pub(crate) fn handle_promise_accept(&mut self, prom: Promise<T>, from: NodeId) {
    #[cfg(feature = "logging")]
    {
        let (r, p) = &self.state;
        debug!(
            self.logger,
            "Self role {:?}, phase {:?}. Incoming message Promise Accept from {}", r, p, from
        );
    }
    if prom.n == self.leader_state.n_leader {
        self.leader_state.set_promise(prom, from, false);
        self.send_accsync(from);
    }
}

fn send_accsync(&mut self, to: NodeId) {
    let current_n = self.leader_state.n_leader;
    let PromiseMetaData {
        n_accepted: prev_round_max_promise_n,
        accepted_idx: prev_round_max_accepted_idx,
        ..
    } = &self.leader_state.get_max_promise_meta();
    let PromiseMetaData {
        n_accepted: followers_promise_n,
        accepted_idx: followers_accepted_idx,
        pid,
        ..
    } = self.leader_state.get_promise_meta(to);
    let followers_decided_idx = self
        .leader_state
        .get_decided_idx(*pid)
        .expect("Received PromiseMetaData but not found in ld");
    // Follower can have valid accepted entries depending on which leader they were previously following
    let followers_valid_entries_idx = if *followers_promise_n == current_n {
        *followers_accepted_idx
    } else if *followers_promise_n == *prev_round_max_promise_n {
        *prev_round_max_accepted_idx.min(followers_accepted_idx)
    } else {
        followers_decided_idx
    };
    let log_sync = self.create_log_sync(followers_valid_entries_idx, followers_decided_idx);
    self.leader_state.increment_seq_num_session(to);
    let acc_sync = AcceptSync {
        n: current_n,
        seq_num: self.leader_state.next_seq_num(to),
        decided_idx: self.get_decided_idx(),
        log_sync,
        #[cfg(feature = "unicache")]
        unicache: self.internal_storage.get_unicache(),
    };
    let msg = Message::SequencePaxos(PaxosMessage {
        from: self.pid,
        to,
        msg: PaxosMsg::AcceptSync(acc_sync),
    });
    self.outgoing.push(msg);
}

fn handle_majority_promises(&mut self) {
    let max_promise_sync = self.leader_state.take_max_promise_sync();
    let decided_idx = self.leader_state.get_max_decided_idx();
    let mut new_accepted_idx = self
        .internal_storage
        .sync_log(self.leader_state.n_leader, decided_idx, max_promise_sync)
        .expect(WRITE_ERROR_MSG);
    if !self.accepted_reconfiguration() {
        if !self.buffered_proposals.is_empty() {
            let entries = std::mem::take(&mut self.buffered_proposals);
            new_accepted_idx = self
                .internal_storage
                .append_entries_without_batching(entries)
                .expect(WRITE_ERROR_MSG);
        }
        if let Some(ss) = self.buffered_stopsign.take() {
            self.internal_storage
                .append_stopsign(ss)
                .expect(WRITE_ERROR_MSG);
            new_accepted_idx = self.internal_storage.get_accepted_idx();
        }
    }
    self.state = (Role::Leader, Phase::Accept);
    self.leader_state
        .set_accepted_idx(self.pid, new_accepted_idx);
    for pid in self.leader_state.get_promised_followers() {
        self.send_accsync(pid);
    }
}

pub(crate) fn handle_decide(&mut self, dec: Decide) {
    if self.check_valid_ballot(dec.n)
        && self.state.1 == Phase::Accept
        && self.handle_sequence_num(dec.seq_num, dec.n.pid) == MessageStatus::Expected
    {
        let new_accepted_idx = self.update_decided_idx_and_get_accepted_idx(dec.decided_idx);
        if let Some(idx) = new_accepted_idx {
            self.reply_accepted(dec.n, idx);
        }
    }
}

